<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Ticket; use Illuminate\Http\Request;
class TicketController extends Controller { public function index(Request $request){$q=$request->user()->isStaff()?Ticket::query():Ticket::where('user_id',$request->user()->id);return response()->json($q->with(['requester','assignee'])->latest()->paginate(15));} public function store(Request $request){$data=$request->validate(['title'=>'required|string|max:180','description'=>'required|string|min:10','priority'=>'required|in:low,normal,high,urgent','category'=>'required|string|max:80']);return response()->json(Ticket::create($data+['user_id'=>$request->user()->id]),201);} public function show(Request $request,Ticket $ticket){abort_unless($request->user()->isStaff()||$ticket->user_id===$request->user()->id,403);return response()->json($ticket->load(['requester','assignee','comments.user']));} public function update(Request $request,Ticket $ticket){abort_unless($request->user()->isStaff(),403);$data=$request->validate(['status'=>'sometimes|in:open,in_progress,pending,resolved,closed','priority'=>'sometimes|in:low,normal,high,urgent','assigned_to'=>'nullable|exists:users,id']);$ticket->update($data);return response()->json($ticket->fresh(['requester','assignee']));} public function destroy(Request $request,Ticket $ticket){abort_unless($request->user()->role==='admin',403);$ticket->delete();return response()->noContent();} }
